<template>
	<view class="page">
		<view class="top-bar">
			<button class="bar-btn back" @tap="handleBack">返回</button>
			<text class="bar-title">我的</text>
			<button
				class="bar-btn save"
				:class="{ disabled: !isSaveEnabled }"
				@tap="handleSave"
			>保存</button>
		</view>

		<scroll-view class="content" scroll-y>
			<view class="section">
				<text class="section-title">个人信息</text>
				<view class="avatar-row">
					<image class="avatar" :src="avatar || '/static/avatar.png'" mode="aspectFill"></image>
					<button class="link-btn" @tap="chooseAvatar">更换头像</button>
				</view>
				<view class="input-row">
					<text class="input-label">用户ID</text>
					<input
						class="input"
						type="text"
						:value="userId"
						placeholder="请输入用户ID"
						placeholder-class="input-placeholder"
						@input="onUserIdInput"
					/>
				</view>
			</view>

			<view class="section">
				<view class="section-header">
					<text class="section-title">我的设备</text>
					<button class="link-btn" @tap="toggleAddForm">
						{{ showAddForm ? '取消' : '＋ 添加设备' }}
					</button>
				</view>

				<view class="add-form" v-if="showAddForm">
					<input
						class="input"
						type="text"
						:value="newDeviceId"
						placeholder="设备ID"
						placeholder-class="input-placeholder"
						@input="onNewDeviceIdInput"
					/>
					<input
						class="input"
						type="text"
						:value="newDeviceName"
						placeholder="设备名称（可选）"
						placeholder-class="input-placeholder"
						@input="onNewDeviceNameInput"
					/>
					<view class="suggest-row" v-if="suggestedDeviceIds.length">
						<text class="suggest-label">快速选择ID：</text>
						<view class="suggest-chips">
							<view
								class="chip"
								v-for="(id, index) in suggestedDeviceIds"
								:key="`id-${index}`"
								@tap="applySuggestedId(id)"
							>{{ id }}</view>
						</view>
					</view>
					<view class="suggest-row" v-if="suggestedDeviceNames.length">
						<text class="suggest-label">快速选择名称：</text>
						<view class="suggest-chips">
							<view
								class="chip"
								v-for="(name, index) in suggestedDeviceNames"
								:key="`name-${index}`"
								@tap="applySuggestedName(name)"
							>{{ name }}</view>
						</view>
					</view>
					<view class="add-actions">
						<button class="outline-btn" @tap="scanDevice">扫码</button>
						<button class="primary-btn" @tap="confirmAddDevice">确定</button>
					</view>
				</view>

				<view class="empty-devices" v-if="devices.length === 0">
					暂未绑定任何设备
				</view>

				<view class="device-list" v-else>
					<view
						class="device-item"
						v-for="(device, index) in devices"
						:key="index"
					>
						<view class="device-info">
							<text class="device-name">{{ device.name || '未命名设备' }}</text>
							<text class="device-id">ID: {{ device.id }}</text>
						</view>
						<view class="device-actions">
							<button
								class="mini-btn"
								:class="{ active: selectedDeviceIndex === index }"
								@tap="selectDevice(index)"
							>{{ selectedDeviceIndex === index ? '当前设备' : '设为当前' }}</button>
							<button class="mini-btn danger" @tap="removeDevice(index)">删除</button>
						</view>
					</view>
				</view>

				<button
					class="outline-btn full"
					v-if="devices.length > 1"
					@tap="switchDevice"
				>切换设备</button>
			</view>
		</scroll-view>
	</view>
</template>

<script>
	import { getDeviceOptions } from '../../utils/api.js'

	export default {
		data() {
			return {
				avatar: '/static/avatar.png',
				userId: '',
				devices: [],
				selectedDeviceIndex: -1,
				originalSettings: null,
				isDirty: false,
				showAddForm: false,
				newDeviceId: '',
				newDeviceName: '',
				saving: false,
				suggestedDeviceIds: [],
				suggestedDeviceNames: []
			}
		},
		onLoad() {
			this.loadSettings()
			this.loadDeviceSuggestions()
		},
		onBackPress() {
			if (this.isDirty) {
				this.confirmExit()
				return true
			}
			return false
		},
		computed: {
			isSaveEnabled() {
				return (
					!!this.userId.trim() &&
					this.isDirty &&
					!this.saving
				)
			}
		},
		methods: {
			loadSettings() {
				const defaultSettings = {
					userId: 'user_0',
					avatar: '/static/avatar.png',
					devices: [],
					selectedDeviceIndex: -1
				}
				const stored = uni.getStorageSync('userSettings') || {}
				const settings = Object.assign({}, defaultSettings, stored)

				this.avatar = settings.avatar || '/static/avatar.png'
				this.userId = settings.userId || ''
				this.devices = Array.isArray(settings.devices) ? settings.devices.slice() : []
				this.selectedDeviceIndex =
					typeof settings.selectedDeviceIndex === 'number'
						? settings.selectedDeviceIndex
						: (this.devices.length > 0 ? 0 : -1)

				this.originalSettings = JSON.parse(JSON.stringify({
					avatar: this.avatar,
					userId: this.userId,
					devices: this.devices,
					selectedDeviceIndex: this.selectedDeviceIndex
				}))
				this.isDirty = false
			},
			async loadDeviceSuggestions() {
				try {
					const { deviceIds, deviceNames } = await getDeviceOptions()
					if (Array.isArray(deviceIds)) {
						this.suggestedDeviceIds = deviceIds.slice(0, 20)
					}
					if (Array.isArray(deviceNames)) {
						this.suggestedDeviceNames = deviceNames.slice(0, 20)
					}
				} catch (error) {
					console.error('加载设备选项失败:', error)
				}
			},
			markDirty() {
				this.isDirty = true
			},
			chooseAvatar() {
				uni.chooseImage({
					count: 1,
					success: (res) => {
						if (res.tempFilePaths && res.tempFilePaths.length > 0) {
							this.avatar = res.tempFilePaths[0]
							this.markDirty()
						}
					}
				})
			},
			onUserIdInput(e) {
				this.userId = e.detail.value
				this.markDirty()
			},
			toggleAddForm() {
				this.showAddForm = !this.showAddForm
				if (!this.showAddForm) {
					this.newDeviceId = ''
					this.newDeviceName = ''
				}
			},
			onNewDeviceIdInput(e) {
				this.newDeviceId = e.detail.value
			},
			onNewDeviceNameInput(e) {
				this.newDeviceName = e.detail.value
			},
			applySuggestedId(id) {
				this.newDeviceId = id
			},
			applySuggestedName(name) {
				this.newDeviceName = name
			},
			scanDevice() {
				uni.scanCode({
					success: (res) => {
						if (res.result) {
							this.newDeviceId = res.result
						}
					}
				})
			},
			confirmAddDevice() {
				const id = this.newDeviceId.trim()
				const name = this.newDeviceName.trim()
				if (!id) {
					uni.showToast({
						title: '请填写设备ID',
						icon: 'none'
					})
					return
				}
				this.devices.push({
					id,
					name
				})
				this.selectedDeviceIndex = this.devices.length - 1
				this.newDeviceId = ''
				this.newDeviceName = ''
				this.showAddForm = false
				this.markDirty()
			},
			selectDevice(index) {
				if (this.selectedDeviceIndex !== index) {
					this.selectedDeviceIndex = index
					this.markDirty()
				}
			},
			switchDevice() {
				const itemList = this.devices.map((device) => device.name || device.id)
				uni.showActionSheet({
					itemList,
					success: (res) => {
						this.selectDevice(res.tapIndex)
					}
				})
			},
			removeDevice(index) {
				uni.showModal({
					title: '删除设备',
					content: '确定删除该设备吗？',
					success: (res) => {
						if (res.confirm) {
							this.devices.splice(index, 1)
							if (this.selectedDeviceIndex === index) {
								this.selectedDeviceIndex = this.devices.length > 0 ? 0 : -1
							} else if (this.selectedDeviceIndex > index) {
								this.selectedDeviceIndex -= 1
							}
							this.markDirty()
						}
					}
				})
			},
			handleBack() {
				if (this.isDirty) {
					this.confirmExit()
				} else {
					uni.navigateBack()
				}
			},
			confirmExit() {
				uni.showModal({
					title: '提示',
					content: '当前修改的内容还未保存，请问是否返回？',
					cancelColor: '#999999',
					confirmColor: '#40C78D',
					success: (res) => {
						if (res.confirm) {
							this.isDirty = false
							uni.navigateBack()
						}
					}
				})
			},
			async handleSave() {
				if (!this.isSaveEnabled) return
				this.saving = true
				const devicesToSave = this.devices.map(device => ({
					id: device.id,
					name: device.name
				}))
				const settings = {
					userId: this.userId.trim(),
					avatar: this.avatar || '/static/avatar.png',
					devices: devicesToSave,
					selectedDeviceIndex: devicesToSave.length > 0 ? Math.max(0, Math.min(this.selectedDeviceIndex, devicesToSave.length - 1)) : -1
				}
				try {
					uni.setStorageSync('userSettings', settings)
					this.originalSettings = JSON.parse(JSON.stringify(settings))
					this.avatar = settings.avatar
					this.userId = settings.userId
					this.devices = settings.devices.map(device => ({ ...device }))
					this.selectedDeviceIndex = settings.selectedDeviceIndex
					this.showAddForm = false
					this.newDeviceId = ''
					this.newDeviceName = ''
					this.isDirty = false
					uni.showToast({
						title: '已保存',
						icon: 'success'
					})
					setTimeout(() => {
						uni.navigateBack()
					}, 500)
				} catch (error) {
					console.error('保存失败:', error)
					uni.showToast({
						title: '保存失败',
						icon: 'none'
					})
				} finally {
					this.saving = false
				}
			}
		}
	}
</script>

<style>
	.page {
		display: flex;
		flex-direction: column;
		height: 100vh;
		background-color: #F5F7FB;
	}

	.top-bar {
		display: flex;
		align-items: center;
		justify-content: space-between;
		padding: 16rpx 32rpx;
		background-color: #FFFFFF;
		box-shadow: 0 6rpx 20rpx rgba(0,0,0,0.06);
	}

	.bar-title {
		font-size: 32rpx;
		font-weight: 700;
		color: #111111;
	}

	.bar-btn {
		padding: 8rpx 24rpx;
		font-size: 26rpx;
		border-radius: 999rpx;
		border: none;
	}

	.bar-btn.back {
		background-color: #F0F0F0;
		color: #333333;
	}

	.bar-btn.save {
		background-color: #40C78D;
		color: #FFFFFF;
	}

	.bar-btn.save.disabled {
		background-color: #D8D8D8;
		color: #FFFFFF;
	}

	.content {
		flex: 1;
		padding: 32rpx;
	}

	.section {
		background-color: #FFFFFF;
		border-radius: 16rpx;
		padding: 32rpx;
		margin-bottom: 32rpx;
		box-shadow: 0 6rpx 20rpx rgba(0,0,0,0.06);
	}

	.section-header {
		display: flex;
		justify-content: space-between;
		align-items: center;
		margin-bottom: 16rpx;
	}

	.section-title {
		font-size: 32rpx;
		font-weight: 700;
		color: #111111;
		margin-bottom: 20rpx;
	}

	.avatar-row {
		display: flex;
		align-items: center;
		gap: 24rpx;
		margin-bottom: 32rpx;
	}

	.avatar {
		width: 120rpx;
		height: 120rpx;
		border-radius: 60rpx;
		background-color: #F0F0F0;
	}

	.input-row {
		display: flex;
		flex-direction: column;
		gap: 16rpx;
	}

	.input-label {
		font-size: 26rpx;
		color: #666666;
	}

	.input {
		padding: 20rpx;
		background-color: #F5F5F5;
		border-radius: 12rpx;
		font-size: 28rpx;
		color: #333333;
	}

	.input-placeholder {
		color: #B3B8C2;
	}

	.link-btn {
		background-color: transparent;
		color: #40C78D;
		font-size: 26rpx;
		padding: 0;
	}

	.add-form {
		background-color: #F9FAFB;
		border-radius: 12rpx;
		padding: 24rpx;
		display: flex;
		flex-direction: column;
		gap: 16rpx;
		margin-bottom: 24rpx;
	}

	.add-actions {
		display: flex;
		justify-content: flex-end;
		gap: 16rpx;
	}

	.suggest-row {
		display: flex;
		flex-direction: column;
		gap: 12rpx;
	}

	.suggest-label {
		font-size: 24rpx;
		color: #8F98A3;
	}

	.suggest-chips {
		display: flex;
		flex-wrap: wrap;
		gap: 12rpx;
	}

	.chip {
		padding: 8rpx 20rpx;
		background-color: #E5F6EE;
		color: #40C78D;
		font-size: 24rpx;
		border-radius: 999rpx;
	}

	.primary-btn,
	.outline-btn {
		padding: 16rpx 32rpx;
		font-size: 26rpx;
		border-radius: 999rpx;
		border: none;
	}

	.primary-btn {
		background-color: #40C78D;
		color: #FFFFFF;
	}

	.outline-btn {
		background-color: #FFFFFF;
		color: #40C78D;
		border: 2rpx solid #40C78D;
	}

	.outline-btn.full {
		width: 100%;
		margin-top: 24rpx;
	}

	.empty-devices {
		padding: 40rpx 0;
		text-align: center;
		font-size: 26rpx;
		color: #A0A7B4;
	}

	.device-list {
		display: flex;
		flex-direction: column;
		gap: 16rpx;
	}

	.device-item {
		display: flex;
		justify-content: space-between;
		align-items: center;
		padding: 24rpx;
		background-color: #F9FAFB;
		border-radius: 12rpx;
	}

	.device-info {
		display: flex;
		flex-direction: column;
		gap: 12rpx;
	}

	.device-name {
		font-size: 28rpx;
		font-weight: 600;
		color: #333333;
	}

	.device-id {
		font-size: 24rpx;
		color: #8F98A3;
	}

	.device-actions {
		display: flex;
		gap: 16rpx;
	}

	.mini-btn {
		font-size: 24rpx;
		padding: 12rpx 24rpx;
		border-radius: 999rpx;
		border: none;
		background-color: #E5F6EE;
		color: #40C78D;
	}

	.mini-btn.active {
		background-color: #40C78D;
		color: #FFFFFF;
	}

	.mini-btn.danger {
		background-color: #FDEBEC;
		color: #F56C6C;
	}
</style>

